"""Characterization tests for the resw_tool.ResourceManager helper.

These tests exercise the offline, deterministic parts of the resource-file
tool (discovery, parsing, wildcard search and update round-trip) using a
throwaway directory tree, so they need no network and no real .resw data.
"""
import importlib.util
from pathlib import Path

import pytest

_MODULE_PATH = Path(__file__).with_name("resw_tool.py")
_spec = importlib.util.spec_from_file_location("resw_tool", _MODULE_PATH)
resw_tool = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(resw_tool)
ResourceManager = resw_tool.ResourceManager


_RESW_TEMPLATE = """<?xml version="1.0" encoding="utf-8"?>
<root>
{items}
</root>
"""


def _write_resw(path: Path, entries):
    items = "\n".join(
        '  <data name="{name}" xml:space="preserve"><value>{value}</value></data>'.format(
            name=name, value=value
        )
        for name, value in entries.items()
    )
    path.write_text(_RESW_TEMPLATE.format(items=items), encoding="utf-8")


@pytest.fixture()
def resources(tmp_path):
    """Two language folders, plus a decoy folder without a Resources.resw."""
    en = tmp_path / "en-US"
    zh = tmp_path / "zh-Hans"
    for d in (en, zh):
        d.mkdir()
    (tmp_path / "NotALanguage").mkdir()

    _write_resw(en / "Resources.resw", {
        "LoginButton.Text": "Log in",
        "LogoutButton.Text": "Log out",
        "Home.Title": "Home",
    })
    _write_resw(zh / "Resources.resw", {
        "LoginButton.Text": "登录",
        "LogoutButton.Text": "登出",
        "Home.Title": "主页",
    })
    return tmp_path


def test_finds_only_language_folders(resources):
    rm = ResourceManager(resources)
    assert set(rm.language_files) == {"en-US", "zh-Hans"}


def test_search_returns_matches_per_language(resources):
    rm = ResourceManager(resources)
    results = rm.search_keys("Log*Button.Text")

    assert set(results) == {"LoginButton.Text", "LogoutButton.Text"}
    assert results["LoginButton.Text"] == {"en-US": "Log in", "zh-Hans": "登录"}
    assert results["LogoutButton.Text"] == {"en-US": "Log out", "zh-Hans": "登出"}


def test_search_no_match_returns_empty(resources):
    rm = ResourceManager(resources)
    assert rm.search_keys("DoesNotExist*") == {}


def test_update_existing_key_round_trips(resources):
    rm = ResourceManager(resources)
    updated = rm.update_key("Home.Title", {"en-US": "Dashboard", "zh-Hans": "仪表盘"})
    assert set(updated) == {"en-US", "zh-Hans"}

    # A fresh manager re-reads the files from disk, proving the write persisted.
    reread = ResourceManager(resources)
    result = reread.search_keys("Home.Title")
    assert result["Home.Title"] == {"en-US": "Dashboard", "zh-Hans": "仪表盘"}


def test_update_new_key_creates_entry(resources):
    rm = ResourceManager(resources)
    rm.update_key("Settings.Title", {"en-US": "Settings"})

    result = ResourceManager(resources).search_keys("Settings.Title")
    assert result == {"Settings.Title": {"en-US": "Settings"}}


def test_update_unknown_language_is_skipped(resources):
    rm = ResourceManager(resources)
    updated = rm.update_key("Home.Title", {"fr-FR": "Accueil"})
    assert updated == []
